    const near=E.map(s).interactables.find(q=>!s.opened.includes(q.id)&&!s.rescued.includes(q.id)&&Math.hypot(q.x-p.x,q.z-p.z)<1.8),ally=s.players.find(q=>q.dead&&q!==p&&Math.hypot(q.x-p.x,q.z-p.z)<1.7);hud.interact.hidden=!near&&!ally;hud.interact.textContent=(ally?'Hold '+nameKey(b.interact)+' · Revive your companion':near?'Click / '+nameKey(b.interact)+' · '+near.name:'');const boss=s.enemies.find(e=>e.group==='boss'&&e.hp>0&&Math.hypot(e.x-p.x,e.z-p.z)<11);if(boss){hud.boss.hidden=false;hud.boss.querySelector('strong').textContent=boss.phase===2?(E.chapters[s.chapter||0].title+' · ENRAGED'):(['THE HUNTSMAN','THE MIRE HUNTSMAN','THE IRON WARDEN','THE SPYMASTER’S CHAMPION','THE DUKE’S CHAMPION'][s.chapter||0]);hud.bossFill.style.width=boss.hp/boss.maxHp*100+'%';}
    if(s.notice&&s.time<s.noticeUntil&&s.notice!==lastNotice){lastNotice=s.notice;notify(s.notice);sound(330,.14,.02);}hud.toast.hidden=now>(hud.noticeUntil||0);
