  function initAudio(){try{const A=window.AudioContext||window.webkitAudioContext;if(A&&!audio)audio=new A();audio?.resume();}catch{}}
  function sound(hz,length=.1,volume=.02){if(!audio||!options.sound||audio.state==='suspended')return;const osc=audio.createOscillator(),gain=audio.createGain();osc.type='triangle';osc.frequency.setValueAtTime(hz,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(Math.max(35,hz*.4),audio.currentTime+length);gain.gain.setValueAtTime(volume,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+length);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+length);}
  let noiseBuffer,lastSwing=-1,lastImpact=-1,lastStep=0;
  function rustle(hz=500,length=.1,volume=.025){if(!audio||!options.sound||audio.state==='suspended')return;try{if(!noiseBuffer){noiseBuffer=audio.createBuffer(1,audio.sampleRate*.3,audio.sampleRate);const data=noiseBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;}const source=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();source.buffer=noiseBuffer;filter.type='lowpass';filter.frequency.value=hz;gain.gain.setValueAtTime(volume,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+length);source.connect(filter);filter.connect(gain);gain.connect(audio.destination);source.start();source.stop(audio.currentTime+length);}catch{}}
  function combatAudio(now){if(phase!=='play'||screen||!s||s.intro<E.INTRO)return;const p=localPlayer();if(p.swingSerial!==lastSwing){lastSwing=p.swingSerial;if(p.action?.kind==='bowRelease')rustle(1800,.09,.035);else if(p.action){rustle(p.action.kind==='heavy'?450:900,.1,.025);sound(p.action.kind==='heavy'?105:190,.08,.018);}}if(s.impactStamp!==lastImpact){lastImpact=s.impactStamp;if(s.impactStamp){rustle(450,.1,.035);sound(70+(s.lastImpactWeight||1)*15,.12,.04);}}if(p.moving&&!p.airY&&now-lastStep>270){lastStep=now;rustle(250,.035,.012);}}
  window.closeOakhaven=close;window.oakhavenIsPlaying=()=>access&&phase==='play'&&!screen&&!paused&&s?.intro>=E.INTRO&&!s.complete&&s.players.some(p=>!p.dead);document.querySelector('#hubPlayOakhaven').addEventListener('click',open);
